  { name: "Number Cruncher Meister tip", rule: "Edge of +5% or more against the sharp fair price (Pinnacle, else the exchange consensus), at a price available at two or more UK bookmaker groups. Always a Pro tip.", set: "2026-11-03" },
  { name: "Fine Margins Meister tip", rule: "Edge between +2% and +5%. Always 0.5 pts. Never a NAP.", set: "2026-10-28" },
  { name: "NAP", rule: "One a day, always a Pro tip, signed off by The Original Meister. Racing NAP: Timeform top-rated, 40%+ chance on exchange prices, best price within 3% of fair at 2+ bookmakers, 1.50 or bigger, and backed by 2+ independent tipsters. If no horse qualifies: a football NAP with a 55%+ chance at a fair price or better at 2+ bookmakers.", set: "2026-10-29" },
  { name: "Best Value", rule: "The biggest edges available at 3+ bookmakers. 2 to 3 a day, keeping at least 2 open so the next one is ready when one starts.", set: "2026-10-29" },
  { name: "Meister Special", rule: "The Original Meister's most likely winners: his highest-chance open tips. 2 to 3 a day, keeping at least 2 open. Shown in place of the NAP when there is no NAP.", set: "2026-10-29" },
  { name: "The Drift Meister tip", rule: "An automated tip (Number Cruncher Meister or Fine Margins Meister) whose price drifts before the start, so the edge at the published price falls below -3% (confirmed at 3+ bookmakers), moves to The Drift Meister. It is still settled at the published price. A shortening never moves a tip. The Original Meister's tips never move. Until 3 Nov 2026 this was The Shortening Meister.", set: "2026-11-03" },
  { name: "Fair price", rule: "Automatic tag for any tip with an edge between -2% and +2%. Any number per day.", set: "2026-10-28" },
  { name: "Edge", rule: "Our chance x decimal price - 1. Each way: average of the win part and the place part.", set: "2026-10-28" },
  { name: "Stakes", rule: "0.5 pt low, 1 pt standard, 1.5-2 pts strong evidence only. Each-way stake is split half win, half place. Never raise stakes to chase losses.", set: "2026-10-28" },
  { name: "Price and stake freeze", rule: "Price, stake and chance are fixed at publication and never edited. Losers are never removed.", set: "2026-10-28" },
  { name: "Settlement", rule: "Football match result and BTTS: 90 minutes. NBA, basketball, hockey: incl. overtime/shootout. Each way: won, placed or lost against the places on the tip. Doubles win only if every leg wins.", set: "2026-10-28", from: "cruncher", removedAt: "2026-11-02T21:06:00+03:00", removedPrice: 3.8, removedEdge: -0.06, removedReason: "The sharp chance moved against us: Pinnacle now 25.1% (was 28.1%), Smarkets 3.95 and Unibet 3.8 (about 25%), so the edge at 3.75 is about -6%." }
